"use strict";

const x11 = require("x11");
const PNG = require("pngjs").PNG;
const fs = require("fs");

function GUI() {
    this.percent = 0.0;
    this.alive = false;
    this.bg = null;
    this.redoBG = false;
    this.incrementInterval = undefined;
    this.barMin = {
        x: 168,
        y: 362
    };
    this.barMax = {
        x: 1112,
        y: 392
    };

    x11.createClient(function(err, display) {
        if (err) {
            console.log(err);
        } else {
            this.X = display.client;
            this.X.require("render", function(err, Render) {
                this.root = display.screen[0].root;
                let black = display.screen[0].black_pixel;
                let white = display.screen[0].white_pixel;
                this.wid = this.X.AllocID();
                this.Render = Render;
                this.X.CreateWindow(
                        this.wid, this.root,
                        0, 0, 1280, 720,
                        0, 0, 0, 0,
                        { 
                            eventMask: x11.eventMask.Exposure 
                        });
                this.X.MapWindow(this.wid);

                this.gc = this.X.AllocID();
                this.X.CreateGC(this.gc, this.wid);

                this.winPicture = this.X.AllocID();
                this.Render.CreatePicture(this.winPicture, this.wid, this.Render.rgb24);

                this.bgPixmap = this.X.AllocID();
                this.X.CreatePixmap(this.bgPixmap, this.wid, 24, 1280, 720);

                this.bgPicture = this.X.AllocID();
                this.Render.CreatePicture(this.bgPicture, this.bgPixmap, this.Render.rgb24);

                this.barGrad = this.X.AllocID();
                this.Render.LinearGradient(this.barGrad, 
                        [0, 0], 
                        [this.barMax.x - this.barMin.x, this.barMax.y - this.barMin.y],
                        [
                            [0,   [0.10, 0.47, 0.55, 1.0] ],
                            [1,   [0.22, 0.91, 0.94, 1.0] ]
                        ]);
            }.bind(this));

            this.X.on("event", function(ev) {
                if (ev.type == 12) {
                    this.alive = true;
                    this.draw();
                }
            }.bind(this));

            this.X.on("error", function(e) {
                console.log("X11 error:", e);
            });

            this.X.on("end", function() {
                console.log("X11 end");
                this.alive = false;
            }.bind(this));
        }
    }.bind(this));
}

GUI.prototype = {
    constructor: GUI,
    setPercent: function(percent) {
        this.percent = Math.max(0, Math.min(percent, 1));
        this.draw();
    },
    getPercent: function() {
        return this.percent;
    },
    setBackground: function(filename, callback) {
        let stream = fs.createReadStream(filename);
        let png = new PNG({filterType: 4});
        let _this = this;
        png.on("parsed", function() {
            if (_this.bg === null || _this.bg.length != this.data.length) {
                _this.bg = new Buffer(this.data.length);
            }
            //console.log("Parsed", this.data);
            for (let y=0; y<this.height; y++) {
                for (let x=0; x<this.width; x++) {
                    let idx = (this.width * y + x) << 2;
                    // RGB -> BGR
                    // XXX In theory, we should be querying the X server
                    // for the correct channel ordering. It is not
                    // guaranteed to be BGR.
                    _this.bg[idx+2] = this.data[idx];
                    _this.bg[idx+1] = this.data[idx+1];
                    _this.bg[idx] = this.data[idx+2];
                }
            }
            _this.redoBG = true;
            if (callback) {
                callback();
            }
        });
        stream.pipe(png);
    },
    incrementTo: function(percent, period, callback) {
        let dpct = Math.min(percent - this.percent, 1-this.percent);
        let pct_per_sec = dpct/period;
        let interval = 33; // ms
        let pct_per_interval = pct_per_sec * interval/1000;
        if (this.incrementInterval !== undefined) {
            clearInterval(this.incrementInterval);
        }
        this.incrementInterval = setInterval(function() {
            if (this.percent < percent) {
                this.setPercent(this.percent + pct_per_interval); 
            } else {
                clearInterval(this.incrementInterval);
                this.incrementInterval = undefined;
                if (callback) {
                    callback();
                }
            }
        }.bind(this), interval);
    },
    draw: function() {
        if (!this.alive) {
            return;
        }

        //this.Render.FillRectangles(1, this.winPicture, [0, 0, 0, 1], [0, 0, 1280, 720]);

        if (this.redoBG) {
            this.X.PutImage(2, this.bgPixmap, this.gc, 1280, 720, 0, 0, 0, 24, this.bg);

            this.redoBG = false;
        }
        this.Render.Composite(3, this.bgPicture, 0, this.winPicture, 0, 0, 0, 0, 0, 0, 1280, 720);

        this.Render.Composite(3, this.barGrad, 0, this.winPicture, 0, 0, 0, 0, 
                this.barMin.x, this.barMin.y, 
                (this.barMax.x - this.barMin.x) * this.percent, 
                this.barMax.y - this.barMin.y);
    },
    cleanup: function() {
        this.X.FreePixmap(this.bgPixmap);
    }
}

module.exports = GUI;

